"""Vector assets traced from the approved orange/navy brand reference.
Wordmark outlines use the bundled Inter family, with the reference's heavy slant.
Run from the repository root. PNG/install icons are generated by render-brand.mjs.
"""
from pathlib import Path
from fontTools.ttLib import TTFont
from fontTools.varLib.instancer import instantiateVariableFont
from fontTools.pens.svgPathPen import SVGPathPen
from fontTools.pens.transformPen import TransformPen
NAVY='#002147';ORANGE='#ff6b00'
upper='M7 131L71 51Q98 17 147 17H320Q330 17 325 26L284 85Q265 113 230 113H132Q99 113 70 135H8Q3 136 7 131Z'
lower='M10 251L64 181Q90 147 131 147H210Q250 147 275 131L231 196Q209 237 166 237H103Q58 237 14 253Q8 255 10 251Z'
mark=lambda a,b:f'<path fill="{a}" d="{upper}"/><path fill="{b}" d="{lower}"/>'
assets=Path('web/assets');assets.mkdir(exist_ok=True)
(assets/'sendrack-mark.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 270">{mark(ORANGE,NAVY)}</svg>\n')
(assets/'sendrack-mark-white.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 270">{mark("#fff","#fff")}</svg>\n')
font=instantiateVariableFont(TTFont(assets/'Inter.ttf'),{'wght':850});glyphs=font.getGlyphSet();cmap=font.getBestCmap();scale=110/font['head'].unitsPerEm
x=188;parts=[]
for char in 'SendRack':
 name=cmap[ord(char)];pen=SVGPathPen(glyphs);transform=TransformPen(pen,(scale,0,+.19*scale,-scale,x,116));glyphs[name].draw(transform)
 parts.append(f'<path fill="{NAVY if len(parts)<4 else ORANGE}" d="{pen.getCommands()}"/>');x+=glyphs[name].width*scale-2.1
width=round(x+20)
body=f'<g transform="translate(4 9) scale(.5)">{mark(ORANGE,NAVY)}</g>'+''.join(parts)
(assets/'sendrack-wordmark.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} 150" role="img" aria-label="SendRack">{body}</svg>\n')
white=body.replace(NAVY,'#fff').replace(ORANGE,'#fff')
(assets/'sendrack-wordmark-white.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} 150" role="img" aria-label="SendRack">{white}</svg>\n')
(assets/'sendrack-logo.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} 180">{body}<text x="188" y="157" fill="{NAVY}" font-family="Arial,sans-serif" font-size="14" letter-spacing="4">DELIVERY MANAGEMENT PLATFORM</text></svg>\n')
# Both native vector icons use the same approved silhouette; notification icons stay monochrome.
Path('android/res/drawable/ic_launcher.xml').write_text(f'<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="108dp" android:height="108dp" android:viewportWidth="108" android:viewportHeight="108"><path android:fillColor="#ffffff" android:pathData="M0,0h108v108h-108z"/><group android:translateX="20" android:translateY="27" android:scaleX="0.2" android:scaleY="0.2"><path android:fillColor="{ORANGE}" android:pathData="{upper}"/><path android:fillColor="{NAVY}" android:pathData="{lower}"/></group></vector>\n')
Path('android/res/drawable/ic_brand_notification.xml').write_text(f'<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="24dp" android:height="24dp" android:viewportWidth="340" android:viewportHeight="270"><path android:fillColor="#ffffff" android:pathData="{upper}"/><path android:fillColor="#ffffff" android:pathData="{lower}"/></vector>\n')
print('Generated shared vector brand assets and native icons.')
